1	import { Request, Response } from 'express';
2	import { supabase } from '../utils/supabase';
3	import { getMember, addRoleToMember, removeRoleFromMember } from '../utils/discord';
4	import { logger } from '../utils/logger';
5	import { RolesSyncRequest, RolesSyncResponse } from '../types/api';
6	import { Member, GenerationRole, Team, MemberTeamRelation, TeamLeader } from '../types/database';
7	
8	export const syncRoles = async (req: Request, res: Response): Promise<void> => {
9	  try {
10	    const { discord_uid } = req.body as RolesSyncRequest;
11	
12	    if (!discord_uid) {
13	      res.status(400).json({ success: false, error: 'discord_uid is required' });
14	      return;
15	    }
16	
17	    // Discordメンバーを取得
18	    const member = await getMember(discord_uid);
19	    if (!member) {
20	      res.status(404).json({ success: false, error: 'Discord member not found' });
21	      return;
22	    }
23	
24	    // DBから部員情報を取得
25	    const { data: memberData, error: memberError } = await supabase
26	      .from('members')
27	      .select('*')
28	      .eq('discord_uid', discord_uid)
29	      .single<Member>();
30	
31	    if (memberError || !memberData) {
32	      logger.error('Failed to fetch member from DB', memberError);
33	      res.status(404).json({ success: false, error: 'Member not found in database' });
34	      return;
35	    }
36	
37	    const rolesAssigned: string[] = [];
38	    const rolesRemoved: string[] = [];
39	
40	    // 1. 期生ロールの同期
41	    const { data: generationRole } = await supabase
42	      .from('generation_roles')
43	      .select('*')
44	      .eq('generation', memberData.generation)
45	      .single<GenerationRole>();
46	
47	    if (generationRole) {
48	      // 期生ロールを付与
49	      const hasRole = member.roles.cache.has(generationRole.discord_role_id);
50	      if (!hasRole) {
51	        await addRoleToMember(member, generationRole.discord_role_id);
52	        rolesAssigned.push(`${memberData.generation}期生`);
53	      }
54	
55	      // 他の期生ロールを削除
56	      const { data: allGenerationRoles } = await supabase
57	        .from('generation_roles')
58	        .select('*')
59	        .neq('generation', memberData.generation);
60	
61	      if (allGenerationRoles) {
62	        for (const otherGenRole of allGenerationRoles) {
63	          if (member.roles.cache.has(otherGenRole.discord_role_id)) {
64	            await removeRoleFromMember(member, otherGenRole.discord_role_id);
65	            rolesRemoved.push(`${otherGenRole.generation}期生`);
66	          }
67	        }
68	      }
69	    }
70	
71	    // 2. 班ロールの同期
72	    // メンバーが所属する班を取得
73	    const { data: memberTeams } = await supabase
74	      .from('member_team_relations')
75	      .select('team_id')
76	      .eq('member_id', memberData.supabase_auth_user_id);
77	
78	    const teamIds = memberTeams?.map((mt: { team_id: string }) => mt.team_id) || [];
79	
80	    // 所属班のロールを取得
81	    const { data: teams } = await supabase
82	      .from('teams')
83	      .select('*')
84	      .in('id', teamIds);
85	
86	    const teamRoleIds = teams?.map((t: Team) => t.discord_role_id) || [];
87	
88	    // 所属班のロールを付与
89	    for (const team of teams || []) {
90	      if (!member.roles.cache.has(team.discord_role_id)) {
91	        await addRoleToMember(member, team.discord_role_id);
92	        rolesAssigned.push(team.name);
93	      }
94	    }
95	
96	    // 全ての班を取得
97	    const { data: allTeams } = await supabase.from('teams').select('*');
98	
99	    // 所属していない班のロールを削除
100	    for (const team of allTeams || []) {
101	      if (
102	        !teamRoleIds.includes(team.discord_role_id) &&
103	        member.roles.cache.has(team.discord_role_id)
104	      ) {
105	        await removeRoleFromMember(member, team.discord_role_id);
106	        rolesRemoved.push(team.name);
107	      }
108	    }
109	
110	    // 3. 班長ロールの同期
111	    const leaderRoleId = process.env.DISCORD_LEADER_ROLE_ID;
112	    if (leaderRoleId) {
113	      const { data: isLeader } = await supabase
114	        .from('team_leaders')
115	        .select('*')
116	        .eq('member_id', memberData.supabase_auth_user_id)
117	        .single<TeamLeader>();
